import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine().trim();

        if(input.contains("=")){
            input = input.split("=")[1];
        }

        String senate = input.replace("\"","").trim();

        int n = senate.length();

        Queue<Integer> r = new LinkedList<>();
        Queue<Integer> d = new LinkedList<>();

        for(int i=0;i<n;i++){
            if(senate.charAt(i)=='R') r.add(i);
            else d.add(i);
        }

        while(!r.isEmpty() && !d.isEmpty()){
            int ri = r.poll();
            int di = d.poll();

            if(ri < di) r.add(ri + n);
            else d.add(di + n);
        }

        System.out.print(r.isEmpty() ? "Dire" : "Radiant");
    }
}

