public class Solution{
 public static void main(String[] args){
  Scanner sc=new Scanner(System.in);
  int n=sc.nextInt();
  String[] grid=new String[n];
  for(int i=0;i<n;i++) grid[i]=sc.next();
  int sx=sc.nextInt(),sy=sc.nextInt(),gx=sc.nextInt(),gy=sc.nextInt();
  boolean[][] vis=new boolean[n][n];
  Queue<int[]> q=new LinkedList<>();
  q.add(new int[]{sx,sy,0}); vis[sx][sy]=true;
  int[] dx={1,-1,0,0},dy={0,0,1,-1};
  while(!q.isEmpty()){
   int[] cur=q.poll();
   int x=cur[0],y=cur[1],d=cur[2];
   if(x==gx&&y==gy){System.out.print(d);return;}
   for(int k=0;k<4;k++){
    int nx=x,ny=y;
    while(nx+dx[k]>=0&&nx+dx[k]<n&&ny+dy[k]>=0&&ny+dy[k]<n&&grid[nx+dx[k]].charAt(ny+dy[k])!='X'){
     nx+=dx[k]; ny+=dy[k];
     if(!vis[nx][ny]){vis[nx][ny]=true;q.add(new int[]{nx,ny,d+1});}
    }
   }
  }
 }
}

