import java.util.*;
import java.util.regex.*;

public class Solution {

    public static int openLock(List<String> deadends, String target) {
        Set<String> dead = new HashSet<>(deadends);
        Set<String> visited = new HashSet<>();

        if (dead.contains("0000")) return -1;

        Queue<String> q = new LinkedList<>();
        q.add("0000");
        visited.add("0000");

        int steps = 0;

        while (!q.isEmpty()) {
            int size = q.size();

            for (int k = 0; k < size; k++) {
                String curr = q.poll();

                if (curr.equals(target))
                    return steps;

                for (int i = 0; i < 4; i++) {
                    int digit = curr.charAt(i) - '0';

                    for (int move : new int[]{-1, 1}) {
                        int nd = (digit + move + 10) % 10;

                        String next = curr.substring(0, i) + nd + curr.substring(i + 1);

                        if (!dead.contains(next) && !visited.contains(next)) {
                            visited.add(next);
                            q.add(next);
                        }
                    }
                }
            }

            steps++;
        }

        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();

        List<String> deadends = new ArrayList<>();

        Matcher m1 = Pattern.compile("deadends=\\[(.*?)\\]").matcher(line);
        Matcher m2 = Pattern.compile("target=\"(.*?)\"").matcher(line);

        if (m1.find()) {
            String inside = m1.group(1).trim();
            if (!inside.isEmpty()) {
                for (String s : inside.split(",")) {
                    deadends.add(s.replace("\"", "").trim());
                }
            }
        }

        String target = "";
        if (m2.find()) {
            target = m2.group(1);
        }

        System.out.println(openLock(deadends, target));
    }
}

