int toInt(char *s){
    int x=0;
    for(int i=0;i<4;i++) x = x*10 + (s[i]-'0');
    return x;
}

void push(char *s){
    strcpy(queue[rear++], s);
}

void pop(char *s){
    strcpy(s, queue[front++]);
}

int openLock(char deadends[][5], int dcount, char target[5]) {

    for(int i=0;i<10000;i++){
        visited[i]=false;
        dead[i]=false;
    }

    for(int i=0;i<dcount;i++)
        dead[toInt(deadends[i])] = true;

    if(dead[0]) return -1;

    char start[5]="0000";
    push(start);
    visited[0]=true;

    int steps=0;

    while(front<rear){

        int size = rear-front;

        for(int k=0;k<size;k++){

            char curr[5];
            pop(curr);

            if(strcmp(curr,target)==0)
                return steps;

            for(int i=0;i<4;i++){

                for(int move=-1; move<=1; move+=2){

                    char next[5];
                    strcpy(next,curr);

                    int d = next[i]-'0';
                    d = (d + move + 10) % 10;
                    next[i] = d + '0';

                    int num = toInt(next);

                    if(!visited[num] && !dead[num]){
                        visited[num]=true;
                        push(next);
                    }
                }
            }
        }

        steps++;
    }

    return -1;
}

