int openLock(vector<string>& deadends, string target) {
    unordered_set<string> dead(deadends.begin(), deadends.end());
    unordered_set<string> vis;

    if (dead.count("0000")) return -1;

    queue<string> q;
    q.push("0000");
    vis.insert("0000");

    int turns = 0;

    while (!q.empty()) {
        int sz = q.size();

        while (sz--) {
            string curr = q.front();
            q.pop();

            if (curr == target) return turns;

            for (int i = 0; i < 4; i++) {
                for (int d : {-1, 1}) {
                    string next = curr;
                    next[i] = (next[i] - '0' + d + 10) % 10 + '0';

                    if (!dead.count(next) && !vis.count(next)) {
                        vis.insert(next);
                        q.push(next);
                    }
                }
            }
        }

        turns++;
    }

    return -1;
}

vector<string> parseDeadends(string s) {
    vector<string> deadends;
    int start = s.find('[');
    int end = s.find(']');

    if (start == string::npos || end == string::npos) return deadends;

    string inside = s.substr(start + 1, end - start - 1);
    string temp;

    for (char c : inside) {
        if (isdigit(c)) temp += c;
        if (temp.size() == 4) {
            deadends.push_back(temp);
            temp.clear();
        }
    }

    return deadends;
}

string parseTarget(string s) {
    int pos = s.find("target=");
    if (pos == string::npos) return "";

    int start = s.find('"', pos);
    int end = s.find('"', start + 1);

    return s.substr(start + 1, end - start - 1);
}

