    getline(cin, input);

    vector<string> deadends = parseDeadends(input);
    string target = parseTarget(input);

    cout << openLock(deadends, target);

    return 0;
}

import java.util.*;

public class Solution {

    static int snakesAndLadders(int[][] board){

        int n=board.length;

        Queue<int[]> q=new LinkedList<>();
        boolean[] vis=new boolean[n*n+1];

        q.offer(new int[]{1,0});
        vis[1]=true;

        while(!q.isEmpty()){

            int[] cur=q.poll();
            int s=cur[0],steps=cur[1];

            if(s==n*n) return steps;

            for(int i=1;i<=6;i++){

                int ns=s+i;
                if(ns>n*n) break;

                int r=(ns-1)/n;
                int c=(ns-1)%n;

                if(r%2==1) c=n-1-c;
                r=n-1-r;

                if(board[r][c]!=-1)
                    ns=board[r][c];

                if(!vis[ns]){
                    vis[ns]=true;
                    q.offer(new int[]{ns,steps+1});
                }
            }
        }

        return -1;
    }

    public static void main(String[] args){

        Scanner sc=new Scanner(System.in);
        String line=sc.nextLine();

        String grid=line.split("=",2)[1];

        grid=grid.substring(2,grid.length()-2);
        String[] rows=grid.split("\\],\\[");

        int n=rows.length;
        int[][] board=new int[n][n];

        for(int i=0;i<n;i++){
            String[] vals=rows[i].split(",");
            for(int j=0;j<n;j++)
                board[i][j]=Integer.parseInt(vals[j]);
        }

        System.out.println(snakesAndLadders(board));
    }
}

