public class Solution {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();

        String arr = line.substring(line.indexOf("[")+1, line.indexOf("]"));
        String[] parts = arr.split(",");

        int[] nums = new int[parts.length];
        for(int i=0;i<parts.length;i++)
            nums[i] = Integer.parseInt(parts[i].trim());

        int limit = Integer.parseInt(line.split("limit=")[1].trim());

        System.out.println(longestSubarray(nums, limit));
    }

    public static int longestSubarray(int[] nums, int limit) {

        Deque<Integer> maxd = new ArrayDeque<>();
        Deque<Integer> mind = new ArrayDeque<>();

        int left = 0, res = 0;

        for(int right=0; right<nums.length; right++) {

            while(!maxd.isEmpty() && nums[right] > maxd.peekLast())
                maxd.pollLast();

            while(!mind.isEmpty() && nums[right] < mind.peekLast())
                mind.pollLast();

            maxd.addLast(nums[right]);
            mind.addLast(nums[right]);

            while(maxd.peekFirst() - mind.peekFirst() > limit) {
                if(maxd.peekFirst() == nums[left]) maxd.pollFirst();
                if(mind.peekFirst() == nums[left]) mind.pollFirst();
                left++;
            }

            res = Math.max(res, right-left+1);
        }

        return res;
    }
}

